import assert from 'node:assert/strict';
import { mkdirSync, writeFileSync, symlinkSync, chmodSync, existsSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { Vault } from './src/core/vault.ts';
import { Person, inProcess, tmp } from './tests/support/broker-support.ts';
const observed=[];
for (const kind of ['missing-control', 'dangling-link', 'inaccessible-directory']) {
 const home=tmp('nova-task3-review-');
 const dir=join(home,'connectors/gmail');
 mkdirSync(dir,{recursive:true,mode:0o700});
 const file=join(dir,'token.json');
 if(kind==='dangling-link')symlinkSync(join(dir,'missing-target'),file);
 if(kind==='inaccessible-directory'){writeFileSync(file,JSON.stringify({refresh_token:'synthetic-probe-value'}),{mode:0o600});chmodSync(dir,0o000);}
 const old=new Vault({home,mode:'file'});old.put('provider/PROBE','synthetic-other-value');
 const b=inProcess(join(home,'broker'));const p=new Person(b.call);await p.setup();
 try {
  const staged=await b.call('create',{source:{migrate:'stage'}});
  const result=await p.approve('create',{source:{migrate:'commit'}});
  observed.push({kind,stage:staged.outcome??staged.error,commit:result.outcome??result.error,legacyRemains:existsSync(join(home,'vault/secrets.json'))});
 }finally{chmodSync(dir,0o700);b.broker.lock();rmSync(home,{recursive:true,force:true});}
}
console.log(JSON.stringify(observed,null,2));
assert.deepEqual(observed.slice(1).map(x=>x.stage),['failed','failed'],'uncertain/nonregular Gmail sources must refuse staging');

